CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id        bigserial PRIMARY KEY,
  tenant_id int  NOT NULL,
  content   text NOT NULL,
  embedding vector(1536)   -- must match the embedding model's dimensions
);

-- Build after the bulk load: much faster than indexing row by row
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64);
CREATE INDEX ON chunks (tenant_id);  -- the filter needs its own index

-- Query time: a wider candidate list buys recall with latency
SET hnsw.ef_search = 100;
-- pgvector 0.8+: keep scanning when the filter discards candidates
SET hnsw.iterative_scan = relaxed_order;

SELECT id, content, 1 - (embedding <=> $1) AS cosine_similarity
FROM chunks
WHERE tenant_id = $2
ORDER BY embedding <=> $1   -- <=> is cosine distance
LIMIT 10;
